package de.tum.cit.aet.artemis.iris.service.pyris.job;

import com.fasterxml.jackson.annotation.JsonInclude;

import de.tum.cit.aet.artemis.course.domain.Course;

/**
 * A PyrisJob representing an in-flight global search Iris answer request.
 * Stores the requesting user's login so status updates can be forwarded via WebSocket.
 *
 * @param jobId        the run id, chosen by the client
 * @param userLogin    the user who asked
 * @param invocationId generated by Artemis for this request and bound into its callback token, because the client can send the same run id again
 */
@JsonInclude(JsonInclude.Include.NON_EMPTY)
public record GlobalSearchAnswerJob(String jobId, String userLogin, String invocationId) implements PyrisJob {

    @Override
    public boolean canAccess(Course course) {
        // Global search answer is not scoped to a specific course.
        return false;
    }
}
